# enrich/<slug>.json (see ENRICH-FORMAT.md): per-category criteria + per-item specs/stores/pick/points, merged by item id
import glob
for _f in sorted(glob.glob(os.path.join(os.path.dirname(os.path.abspath(__file__)),"enrich","*.json"))):
    _e=json.load(open(_f,encoding="utf-8"))
    for it in DATA:
        _x=_e.get("items",{}).get(it["id"])
        if _x:
            it["criteria"]=_e.get("criteria",[])
            for _k in ("specs","stores","pick","pickWhy","points"):
                if _k in _x: it[_k]=_x[_k]
