# --- Per-category share pages + social-preview images (WhatsApp etc.) ---
# Share URL:  BASE + "c/<slug>/"  -> static page with OG tags + image og/<slug>.jpg, then redirects to BASE#<slug>.
# The image is a screenshot of og/<slug>.html (headless Chrome) — regenerated only when the category's tiles/text change.
import hashlib, subprocess, shutil, html as _html
CHROME=os.environ.get("CHROME","/Applications/Google Chrome.app/Contents/MacOS/Google Chrome")
def _nis(n): return "₪"+format(int(n),",")
cat_og_tpl=r"""<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><base href="../">
<link href="https://fonts.googleapis.com/css2?family=Rubik:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
*{margin:0;box-sizing:border-box}
html,body{width:1200px;height:630px;overflow:hidden}
body{font-family:"Rubik","Heebo","Arial Hebrew","Arial",sans-serif;background:#f5f0e8;position:relative}
.mosaic{position:absolute;top:0;bottom:0;left:0;width:690px;display:grid;grid-template-columns:repeat(__COLS__,1fr);grid-auto-rows:1fr;gap:9px;padding:9px;background:#f5f0e8}
.tile{background:#fbf8f2;overflow:hidden;border-radius:11px;box-shadow:inset 0 0 0 1px rgba(255,255,255,.5);display:flex;align-items:center;justify-content:center}
.tile img{width:100%;height:100%;object-fit:cover;display:block}
.scrim{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(245,240,232,0) 0%,rgba(245,240,232,0) 48%,rgba(245,240,232,.7) 58%,#f5f0e8 66%),linear-gradient(0deg,rgba(51,44,37,.12),rgba(51,44,37,0) 22%)}
.txt{position:relative;z-index:2;width:520px;height:630px;margin-inline-end:auto;display:flex;flex-direction:column;justify-content:center;padding:50px 60px}
.kick{font-size:19px;font-weight:700;letter-spacing:.12em;color:#946f3c;display:flex;align-items:center;gap:12px}
.kick::before{content:"";width:34px;height:3px;border-radius:3px;background:#b08a54}
.ic{font-size:60px;margin:14px 0 0;line-height:1}
h1{font-size:__H1__px;font-weight:900;color:#2c241c;line-height:1.02;letter-spacing:-.02em;margin:8px 0 14px;text-wrap:balance}
.lead{font-size:22px;color:#5c5148;font-weight:500;line-height:1.4;max-width:400px}
.pick{margin-top:14px;font-size:20px;font-weight:700;color:#7a5a12}
.badges{margin-top:24px;display:flex;gap:10px;flex-wrap:wrap}
.badge{display:inline-flex;align-items:center;gap:8px;background:#332c25;color:#f5ecd9;font-size:17px;font-weight:700;padding:10px 18px;border-radius:99px}
.badge.g{background:#efe3c8;color:#6f520d}
</style></head><body>
<div class="mosaic">__TILES__</div><div class="scrim"></div>
<div class="txt"><div class="kick">הבית שלנו · לוח החלטות</div><div class="ic">__ICON__</div><h1>__LABEL__</h1>
<div class="lead">__LEAD__</div>__PICK__<div class="badges">__BADGES__</div></div></body></html>"""
def cat_share(c):
    slug=c.get("slug") or c["key"]; label=c["label"]; icon=c.get("icon","")
    its=[d for d in DATA if d["cat"]==c["key"] and d.get("type")=="product" and not d.get("deleted") and not d.get("hidden")]
    prices=[d["price"] for d in its if isinstance(d.get("price"),(int,float))]
    pick=next((d for d in its if d.get("pick")),None)
    imgs=[d.get("imgs",[d.get("img")])[0] if d.get("imgs") else d.get("img") for d in its]; imgs=[i for i in imgs if i][:12]
    n=len(imgs); cols=2 if n<=4 else (3 if n<=9 else 4)
    tiles="".join(f'<div class="tile"><img src="{_html.escape(i)}" onerror="this.style.display=\'none\'"></div>' for i in imgs) or '<div class="tile"></div>'
    price_txt=("\u202a"+_nis(min(prices))+" – "+_nis(max(prices))+"\u202c") if len(prices)>1 and min(prices)!=max(prices) else (_nis(prices[0]) if prices else "")
    lead=c.get("group","") or "לוח החלטות לבית"
    pick_html=f'<div class="pick">⭐ ההמלצה שלנו: {_html.escape(pick["name"][:46])}</div>' if pick else ""
    badges=f'<span class="badge">{len(its)} מוצרים</span>'+(f'<span class="badge g">{price_txt}</span>' if price_txt else "")
    h1=64 if len(label)<=10 else (52 if len(label)<=16 else 42)
    page=(cat_og_tpl.replace("__COLS__",str(cols)).replace("__TILES__",tiles).replace("__ICON__",icon).replace("__LABEL__",_html.escape(label))
          .replace("__LEAD__",_html.escape(lead)).replace("__PICK__",pick_html).replace("__BADGES__",badges).replace("__H1__",str(h1)))
    return slug,label,its,pick,price_txt,page
os.makedirs(os.path.join(REPO,"og"),exist_ok=True); os.makedirs(os.path.join(REPO,"c"),exist_ok=True)
_chrome_ok=os.path.exists(CHROME)
for _c in [c for c in CATS if c["key"]!="all"]:
    slug,label,its,pick,price_txt,page=cat_share(_c)
    h=hashlib.md5(page.encode("utf-8")).hexdigest()
    hp=os.path.join(REPO,"og",slug+".hash"); jp=os.path.join(REPO,"og",slug+".jpg")
    old=open(hp).read().strip() if os.path.exists(hp) else ""
    open(os.path.join(REPO,"og",slug+".html"),"w",encoding="utf-8").write(page)
    if (old!=h or not os.path.exists(jp)) and _chrome_ok:
        try:
            png=os.path.join(REPO,"og",slug+".png")
            subprocess.run([CHROME,"--headless=new","--disable-gpu","--hide-scrollbars","--window-size=1200,630","--virtual-time-budget=9000","--screenshot="+png,"file://"+os.path.join(REPO,"og",slug+".html")],timeout=90,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
            from PIL import Image
            Image.open(png).convert("RGB").save(jp,quality=86); os.remove(png); open(hp,"w").write(h)
        except Exception as e: print("og image failed for",slug,e)
    # share page (static OG + redirect to the board with the category selected)
    title=f"{label} — לוח החלטות · הבית שלנו"
    desc=f"{len(its)} מוצרים"+(f" · {price_txt}" if price_txt else "")+(f" · ⭐ המלצה: {pick['name'][:60]}" if pick else "")
    share=f"""<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{_html.escape(title)}</title>
<meta property="og:type" content="website"><meta property="og:url" content="{BASE}c/{slug}/">
<meta property="og:title" content="{_html.escape(title)}"><meta property="og:description" content="{_html.escape(desc)}">
<meta property="og:site_name" content="הבית שלנו"><meta property="og:locale" content="he_IL">
<meta property="og:image" content="{BASE}og/{slug}.jpg"><meta property="og:image:type" content="image/jpeg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="{BASE}og/{slug}.jpg">
<meta http-equiv="refresh" content="0;url={BASE}#{slug}"><script>location.replace("{BASE}#{slug}")</script>
</head><body style="font-family:Arial,sans-serif;text-align:center;padding:40px"><p><a href="{BASE}#{slug}">פתיחת הקטגוריה «{_html.escape(label)}» בלוח ההחלטות</a></p></body></html>"""
    os.makedirs(os.path.join(REPO,"c",slug),exist_ok=True)
    open(os.path.join(REPO,"c",slug,"index.html"),"w",encoding="utf-8").write(share)

print("board built | items",len(DATA),"| bytes",len(out),"| + /picks/ fresh copy | og.html:",len(og_cats),"cats,",len(og_tiles),"mosaic tiles")
